            {speech.phase !== 'idle' && <button type="button" onClick$={() => voiceController.value?.stop()} aria-label={recording ? 'Cancel recording' : 'Stop voice'}><VoiceIcon kind="stop" />{recording ? 'Cancel' : 'Stop'}</button>}
