interface Draft {
  name: string;
  brief: string;
  audienceId: string;
  baseRevision: number;
}

interface ProjectFlowState {
  active: boolean;
  list: ProjectSummary[];
  listLoading: boolean;
  listError: string;
  listAttempt: number;
  detail: ProjectDetail | null;
  detailLoading: boolean;
  detailAttempt: number;
