    if (!pair) break;
    const [i, j] = pair;
    const a = toOklab(clusters[i]);
    const b = toOklab(clusters[j]);
    const score = clusters[i].score + clusters[j].score;
    const weight = clusters[i].score / score;
    clusters[i] = {
