export const library = createLibrary({
  id: "baste-workbench",
  root: ROOT,
  components: [Workbench, Section, Note, Preview, ColorField, FontField, EdgeField, Choice, Option, Palette, Swatch, Contrast, Compare, Variant, Question, Buttons, Button, SaveStatus],
