  await assert.rejects(clairic({ state: "s", fields: { a: { type: "text" } } }, { fetcher: failing as typeof fetch }), (e: unknown) => e instanceof ClairicError && !e.message.includes("secret"));
  const limited = async () => new Response("", { status: 429 });
