export interface ImageRef { href: string; width: number; height: number }

export function imageRef(data: Buffer, width: number, height: number): ImageRef {
  const info = parseImageDimensions(new Uint8Array(data.buffer, data.byteOffset, data.byteLength));
  const format = info?.format === "jpeg" ? "jpeg" : "png";
  return { href: `data:image/${format};base64,${data.toString("base64")}`, width, height };
}

/**
 * A rectangle of an image, padded a little so edges aren't clipped. Small
 * things are enlarged to `minSide` (up to 4×); `maxSide` shrinks large ones,
 * for a model's input limit. Only the rectangle is rendered.
 */
export function crop(image: ImageRef, box: Box, opts: { pad?: number; minSide?: number; maxSide?: number } = {}): { png: Buffer; box: Box } {
  const pad = opts.pad ?? 6;
  const x = Math.max(0, box.x - pad), y = Math.max(0, box.y - pad);
  const w = Math.min(image.width, box.x + box.w + pad) - x, h = Math.min(image.height, box.y + box.h + pad) - y;
  let zoom = Math.min(4, Math.max(1, (opts.minSide ?? 96) / Math.min(w, h)));
  if (opts.maxSide) zoom = Math.min(zoom, opts.maxSide / Math.max(w, h));
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}"><image x="${-x}" y="${-y}" width="${image.width}" height="${image.height}" preserveAspectRatio="none" href="${image.href}"/></svg>`;
  return { png: new Resvg(svg, { fitTo: { mode: "zoom", value: zoom } }).render().asPng(), box: { x, y, w, h } };
}

/**
 * The region alone on transparency. SAM 3 returns white-on-black masks at
 * the source's size, so the mask is cropped to the same rectangle and only
 * that is drawn: rendering the whole page per region was what made this slow.
 */
export function regionCutout(image: ImageRef, mask: Buffer, box: Box, minSide = 96): Buffer | undefined {
  const info = parseImageDimensions(new Uint8Array(mask.buffer, mask.byteOffset, mask.byteLength));
  if (!info || (info.format !== "png" && info.format !== "jpeg")) return undefined;
  const source = crop(image, box, { pad: 2, minSide: 0 });
  const local = crop(imageRef(mask, image.width, image.height), box, { pad: 2, minSide: 0 }).png;
  const size = { width: source.box.w, height: source.box.h };
  const cut = cutout({ png: source.png, ...size }, { png: local });
  return Math.min(size.width, size.height) < minSide ? crop(imageRef(cut, size.width, size.height), { x: 0, y: 0, w: size.width, h: size.height }, { pad: 0, minSide }).png : cut;
}

