// Records a real Sample-tab run as high-quality frames via the CDP screencast,
// with a drawn cursor and a log of beat times, then assembles an MP4.
import { chromium } from "playwright";
import { mkdirSync, writeFileSync, rmSync } from "node:fs";
import { execFileSync } from "node:child_process";

const OUT = process.argv[2] ?? "/tmp/sample-take";
rmSync(OUT, { recursive: true, force: true });
mkdirSync(`${OUT}/frames`, { recursive: true });
const W = 1920, H = 1080;

const browser = await chromium.launch({ executablePath: "/usr/bin/google-chrome", args: ["--no-sandbox", "--hide-scrollbars"] });
const context = await browser.newContext({ viewport: { width: W, height: H }, deviceScaleFactor: 1 });
await context.addInitScript(() => {
  // A drawn cursor: headless Chrome renders none. Ink arrow with a press ring.
  addEventListener("DOMContentLoaded", () => {
    const c = document.createElement("div");
    c.id = "__cursor";
    c.innerHTML = `<svg width="28" height="28" viewBox="0 0 28 28"><path d="M4 3l17 9-7.5 2L10 22z" fill="#1c1b19" stroke="#f7f3ea" stroke-width="1.6" stroke-linejoin="round"/></svg><i></i>`;
    Object.assign(c.style, { position: "fixed", left: "0", top: "0", zIndex: "2147483647", pointerEvents: "none", transform: "translate(-200px,-200px)", willChange: "transform" });
    const ring = c.querySelector("i");
    Object.assign(ring.style, { position: "absolute", left: "-14px", top: "-14px", width: "34px", height: "34px", borderRadius: "50%", border: "2px solid #d2402a", opacity: "0", transition: "opacity .25s, transform .35s", transform: "scale(.4)" });
    document.body.appendChild(c);
    addEventListener("mousemove", (e) => { c.style.transform = `translate(${e.clientX - 4}px, ${e.clientY - 3}px)`; }, true);
    addEventListener("mousedown", () => { ring.style.transition = "none"; ring.style.opacity = "1"; ring.style.transform = "scale(.4)"; requestAnimationFrame(() => { ring.style.transition = "opacity .45s, transform .45s"; ring.style.opacity = "0"; ring.style.transform = "scale(1.3)"; }); }, true);
  });
});
const page = await context.newPage();
const cdp = await context.newCDPSession(page);
const frames = [];
let t0 = 0;
cdp.on("Page.screencastFrame", async ({ data, sessionId, metadata }) => {
  const i = frames.length;
  frames.push({ i, t: metadata.timestamp });
  writeFileSync(`${OUT}/frames/${String(i).padStart(6, "0")}.jpg`, Buffer.from(data, "base64"));
  await cdp.send("Page.screencastFrameAck", { sessionId }).catch(() => {});
});
const beats = [];
const mark = (name) => { const t = Date.now() / 1000 - t0; beats.push({ name, t: +t.toFixed(2) }); console.log(`[${t.toFixed(1)}s] ${name}`); };
let mx = W / 2, my = H / 2;
const move = async (x, y, ms = 700) => {
  const steps = Math.max(8, Math.round(ms / 16));
  const sx = mx, sy = my;
  for (let k = 1; k <= steps; k++) {
    const e = 0.5 - Math.cos((Math.PI * k) / steps) / 2;
    await page.mouse.move(sx + (x - sx) * e, sy + (y - sy) * e);
    await page.waitForTimeout(16);
  }
  mx = x; my = y;
};
const moveTo = async (locator, ms) => { const b = await locator.boundingBox(); await move(b.x + b.width / 2, b.y + b.height / 2, ms); };
const click = async (locator, ms) => { await moveTo(locator, ms); await page.waitForTimeout(150); await page.mouse.down(); await page.waitForTimeout(70); await page.mouse.up(); };
const typeSlow = async (text, delay = 70) => { for (const ch of text) { await page.keyboard.type(ch); await page.waitForTimeout(delay); } };
const scrollBy = async (dy, ms = 900) => {
  const steps = Math.round(ms / 16); let done = 0;
  for (let k = 1; k <= steps; k++) { const e = 0.5 - Math.cos((Math.PI * k) / steps) / 2; const target = Math.round(dy * e); await page.mouse.wheel(0, target - done); done = target; await page.waitForTimeout(16); }
};

await page.goto("http://localhost:5173/gui/?persona=nightmarketcoder&tab=sample", { waitUntil: "networkidle" });
await page.waitForSelector("#sample-url");
await page.waitForTimeout(3800); // past the dev Click-to-Source overlay
await page.mouse.move(mx, my);
await cdp.send("Page.startScreencast", { format: "jpeg", quality: 92, maxWidth: W, maxHeight: H, everyNthFrame: 1 });
t0 = Date.now() / 1000;
await page.waitForTimeout(900);
mark("open");

await click(page.locator("#sample-url"), 900);
await page.waitForTimeout(200);
mark("type-url");
await typeSlow("https://ichiran.com", 55);
await page.waitForTimeout(400);
await click(page.getByRole("button", { name: "Stop looking for icon" }), 800);
await page.waitForTimeout(350);
await click(page.locator("#sample-look"), 600);
mark("type-look");
await typeSlow("sign", 90);
await page.keyboard.press("Enter");
await page.waitForTimeout(600);
mark("look-ready");
await click(page.getByRole("button", { name: "Sample this site" }), 900);
mark("sampling");
await move(1240, 760, 1200);
await page.waitForSelector("#sample-list-title", { timeout: 180000 });
mark("result");
await page.waitForTimeout(1200);

// The capture with numbered finds, and the page-level reading.
const fig = page.locator("section[aria-labelledby=sample-page-title]");
const top = (await fig.boundingBox()).y;
await scrollBy(top - 90, 1100);
await page.waitForTimeout(700);
mark("capture");
const boxes = page.locator("figure button[aria-label^='Sample']");
for (const n of [0, 1, 2]) { await moveTo(boxes.nth(n), 700); await page.waitForTimeout(700); }
mark("why-screen");
await move(1560, 420, 900);
await page.waitForTimeout(1600);

// The ranked samples.
const list = page.locator("#sample-list-title");
await scrollBy((await list.boundingBox()).y - 110, 1300);
await page.waitForTimeout(600);
mark("samples");
const first = page.locator("ol > li[id^=sample-]").first();
await moveTo(first, 900);
await page.waitForTimeout(1600);
await click(first.locator("input"), 700);
mark("why-type");
await typeSlow("Feels like a stall at 2am", 55);
await page.waitForTimeout(300);
await click(first.getByRole("button", { name: /^Keep/ }), 700);
await first.getByRole("button", { name: "On the moodboard" }).waitFor({ timeout: 30000 });
mark("kept");
await page.waitForTimeout(1400);

// The moodboard, with the kept original pinned.
await scrollBy(-20000, 1000);
await page.waitForTimeout(300);
const tab = page.getByRole("radio", { name: "Moodboard" }).or(page.getByRole("tab", { name: "Moodboard" })).or(page.locator("[role=radiogroup] >> text=Moodboard")).first();
await click(tab, 1000);
await page.waitForTimeout(1500);
const ref = page.locator("img[src*='/samples/']").first();
await ref.waitFor({ timeout: 10000 });
await page.evaluate(() => document.querySelector("img[src*='/samples/']")?.scrollIntoView({ block: "center", behavior: "smooth" }));
await page.waitForTimeout(900);
mark("moodboard");
await moveTo(ref, 900);
await page.waitForTimeout(2200);
mark("end");

await cdp.send("Page.stopScreencast");
await page.waitForTimeout(300);
await browser.close();

// Constant 30 fps: each screencast frame holds until the next one arrived.
const start = frames[0].t;
const fps = 30, total = frames.at(-1).t - start + 0.5;
const list2 = [];
for (let k = 0, f = 0; k < Math.ceil(total * fps); k++) {
  const t = start + k / fps;
  while (f + 1 < frames.length && frames[f + 1].t <= t) f++;
  list2.push(`file 'frames/${String(frames[f].i).padStart(6, "0")}.jpg'\nduration ${1 / fps}`);
}
writeFileSync(`${OUT}/concat.txt`, list2.join("\n") + "\n");
// Beats were marked against wall time from screencast start; align them to the first frame.
const offset = start - t0;
writeFileSync(`${OUT}/beats.json`, JSON.stringify(beats.map((b) => ({ ...b, t: +(b.t - offset).toFixed(2) })), null, 2));
execFileSync("ffmpeg", ["-y", "-loglevel", "error", "-f", "concat", "-safe", "0", "-i", `${OUT}/concat.txt`, "-vf", "scale=1920:1080:flags=lanczos,format=yuv420p", "-c:v", "libx264", "-preset", "slow", "-crf", "16", "-r", "30", "-movflags", "+faststart", `${OUT}/take.mp4`], { cwd: OUT });
console.log("frames", frames.length, "duration", total.toFixed(1), "s");

