// Narration from SCRIPT.md: one MP3 per line with word timings, via ElevenLabs George on fal.
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { falRun, falDownloadBytes } from "../../dist/src/assets/fal.js";
const lines = [...readFileSync("SCRIPT.md", "utf8").matchAll(/^## (\w+)\n> (.+)$/gm)].map(([, id, text]) => ({ id, text }));
const out = [];
for (const { id, text } of lines) {
  const mp3 = `narration/${id}.mp3`, meta = `narration/${id}.json`;
  let words;
  if (existsSync(meta) && JSON.parse(readFileSync(meta, "utf8")).text === text) words = JSON.parse(readFileSync(meta, "utf8")).words;
  else {
    const r = await falRun("fal-ai/elevenlabs/tts/turbo-v2.5", { text, voice: "George", stability: 0.55, similarity_boost: 0.75, speed: 1, timestamps: true }, { key: process.env.FAL_KEY });
    writeFileSync(mp3, await falDownloadBytes(r.audio.url, 10e6));
    // Character timings → words.
    words = []; let cur = null;
    for (const seg of r.timestamps ?? []) for (let i = 0; i < seg.characters.length; i++) {
      const ch = seg.characters[i], s = seg.character_start_times_seconds[i], e = seg.character_end_times_seconds[i];
      if (/\s/.test(ch)) { if (cur) { words.push(cur); cur = null; } continue; }
      if (!cur) cur = { text: "", start: s, end: e }; cur.text += ch; cur.end = e;
    }
    if (cur) words.push(cur);
    writeFileSync(meta, JSON.stringify({ voice: "George", model: "fal-ai/elevenlabs/tts/turbo-v2.5", text, words }, null, 2));
  }
  const duration = +execFileSync("ffprobe", ["-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", mp3]).toString().trim();
  out.push({ id, text, duration, words });
  console.log(id.padEnd(6), duration.toFixed(2), "s", words.length, "words");
}
writeFileSync("narration/lines.json", JSON.stringify(out, null, 2));
EOF
