const END = 38.4, SCREEN = 5.4, CLOSE = 33.4;

// Captions: phrases of at most six words, broken at punctuation, timed to the voice.
const caps = [];
for (const l of lines) {
  let cur = [];
  const flush = () => { if (!cur.length) return; caps.push({ text: cur.map((w) => w.text).join(" "), start: AT[l.id] + cur[0].start, end: AT[l.id] + cur.at(-1).end }); cur = []; };
  for (const w of l.words) { cur.push(w); if (/[,.:;]$/.test(w.text) || cur.length >= 6) flush(); }
  flush();
}
for (let i = 0; i < caps.length; i++) caps[i].end = Math.min(caps[i].end + 0.25, caps[i + 1]?.start ?? END);
const esc = (s) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;");
const capHtml = caps.map((c, i) => `      <div id="cap-${i}" class="clip cap" data-start="${c.start.toFixed(2)}" data-duration="${(c.end - c.start).toFixed(2)}" data-track-index="9"><span>${esc(c.text)}</span></div>`).join("\n");
const voiceHtml = lines.map((l) => `      <audio id="vo-${l.id}" src="narration/${l.id}.mp3" data-start="${AT[l.id]}" data-duration="${l.duration.toFixed(3)}" data-volume="1" data-track-index="10"></audio>`).join("\n");
const vtt = "WEBVTT\n\n" + caps.map((c) => `${ts(c.start)} --> ${ts(c.end)}\n${c.text}\n`).join("\n");
function ts(t) { const h = Math.floor(t / 3600), m = Math.floor(t / 60) % 60, s = (t % 60).toFixed(3).padStart(6, "0"); return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${s}`; }
